import React, { useState } from "react";
import {
  Container,
  Box,
  Typography,
  TextField,
  Button,
  MenuItem
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../contexts/AuthContext"; // <- import context

export default function Login() {
  const navigate = useNavigate();
  const { setMobileNumber } = useAuth(); // <- context setter

  const [phone, setPhone] = useState("");
  const [countryCode, setCountryCode] = useState("+91");

  const handleLogin = () => {
    if (!phone) return alert("Please enter mobile number");

    // Save mobile number to context
    setMobileNumber(countryCode + phone);

    // Navigate to OTP page
    navigate("/otp");
  };

  return (
    <Container
      maxWidth="xl"
      sx={{
        height: "100vh",
        position: "relative",
        display: "flex",
        alignItems: "center",
        justifyContent: "center"
      }}
    >
      {/* TOP LEFT LOGO */}
      <Box sx={{ position: "absolute", top: "25px", left: "25px" }}>
        <img src="/venum-logo.png" alt="Venum" style={{ width: "120px" }} />
      </Box>

      {/* CENTER LOGIN CONTENT */}
      <Box sx={{ width: "100%", maxWidth: "450px", textAlign: "center", margin: "0 auto" }}>
        <Typography variant="h4" fontWeight="bold" mb={1}>Welcome Back</Typography>
        <Typography color="text.secondary" mb={4}>Enter your mobile number to continue</Typography>

        {/* PHONE INPUT */}
        <Box sx={{ display: "flex", gap: 2, mb: 4 }}>
          {/* COUNTRY CODE */}
          <TextField
            select
            value={countryCode}
            onChange={(e) => setCountryCode(e.target.value)}
            sx={{ width: "120px" }}
          >
            <MenuItem value="+91">+91</MenuItem>
            <MenuItem value="+1">+1</MenuItem>
            <MenuItem value="+44">+44</MenuItem>
          </TextField>

          {/* MOBILE NUMBER */}
          <TextField
            fullWidth
            placeholder="Mobile Number"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </Box>

        {/* LOGIN BUTTON */}
        <Button
          fullWidth
          variant="contained"
          onClick={handleLogin}
          sx={{
            backgroundColor: "black",
            color: "white",
            height: "50px",
            fontSize: "16px",
            borderRadius: "8px",
            "&:hover": { backgroundColor: "#222" }
          }}
        >
          Login
        </Button>
      </Box>
    </Container>
  );
}