import React from "react";

const Purchase = () => {

  const handlePayment = async () => {

    try {
      // 1️⃣ Call Strapi backend to create order
      const response = await fetch("http://localhost:1337/api/payments/create-order", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          amount: 500,       // ₹500 course price
          courseId: 1,
          userId: 1,         // Replace with logged in user
        }),
      });

      const data = await response.json();
      const { order } = data;

      // 2️⃣ Open Razorpay checkout
      const options = {
        key: "YOUR_RAZORPAY_KEY_ID", // frontend key_id
        amount: order.amount,
        currency: order.currency,
        name: "My Courses",
        description: "Course Purchase",
        order_id: order.id,
        handler: async function (response) {
          console.log("Payment success:", response);

          // ✅ Verify payment on backend
          await fetch("http://localhost:1337/api/payments/verify-payment", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(response),
          });

          alert("Payment Successful!");
        },
        prefill: {
          name: "User Name",
          email: "user@example.com",
          contact: "9999999999",
        },
        theme: {
          color: "#000",
        },
      };

      const rzp = new window.Razorpay(options);
      rzp.open();

    } catch (err) {
      console.error(err);
      alert("Something went wrong");
    }

  };

  return (
    <div style={{ padding: 40 }}>
      <h2>Course Purchase Page</h2>
      <button onClick={handlePayment} style={{ padding: "10px 20px", fontSize: 16, background: "black", color: "white" }}>
        Buy Course
      </button>
    </div>
  );
};

export default Purchase;