import React from "react";
import { useNavigate } from "react-router-dom";

const CourseDetails = () => {

  const navigate = useNavigate();

  const buyCourse = () => {

    const token = localStorage.getItem("token");

    if(!token){
      navigate("/login");
    }else{
      navigate("/purchase");
    }

  };

  return (

    <div style={{padding:40}}>

      <h1>React Course</h1>

      <button onClick={buyCourse}>
        Buy Now
      </button>

    </div>

  );

};

export default CourseDetails;