import React, { useState } from "react";
import { Link } from "react-router-dom";
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Box,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
} from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";
import { useTheme } from "@mui/material/styles";
import CloseIcon from "@mui/icons-material/Close";

// Navigation links
const navLinks = [
  { name: "Campus Fellowship", path: "/campus-fellowship" },
  { name: "Online Fellowship", path: "/online-fellowship" },
  { name: "Hospitals", path: "/hospitals" },
  { name: "Blogs", path: "/blogs" },
  { name: "About", path: "/about" },
  { name: "FAQs", path: "/faqs" },
  { name: "Contact", path: "/contact" },
];

const Header = ({ applyBtnColor = "secondary" }) => {
  const theme = useTheme();
  const [drawerOpen, setDrawerOpen] = useState(false);

  const toggleDrawer = () => setDrawerOpen(!drawerOpen);

  const btnColor =
    applyBtnColor === "primary"
      ? theme.palette.primary.main
      : theme.palette.secondary.main;

  return (
    <>
      <AppBar position="fixed" sx={{ background: "#fff"}} elevation={3}>
        <Toolbar
          sx={{
            display: "flex",
            justifyContent: "space-between",
            px: { xs: 2, md: 10 },
          }}
        >
          {/* Left: Logo + Nav */}
          <Box sx={{ display: "flex", alignItems: "center", gap: 3 }}>
            <Typography
              variant="h6"
              component={Link}
              to="/"
              sx={{
                textDecoration: "none",
                color: "#000",
                fontWeight: 600,
                fontFamily: "'Figtree', sans-serif",
              }}
            >
              MyLogo
            </Typography>

            {/* Desktop Nav */}
            <Box sx={{ display: { xs: "none", md: "flex" }, gap: 2 }}>
              {navLinks.map((link) => (
                <Button
                  key={link.name}
                  component={Link}
                  to={link.path}
                  sx={{
                    color: "#000",
                    textTransform: "none",
                    fontFamily: "'Figtree', sans-serif",
                    fontWeight: 600,
                    fontSize: 14,
                  }}
                >
                  {link.name}
                </Button>
              ))}
            </Box>
          </Box>

          {/* Right: Apply Button */}
          <Box sx={{ display: { xs: "none", md: "flex" } }}>
            <Button
              variant="contained"
              component={Link}
              to="/apply"
              sx={{
                backgroundColor: btnColor,
                color: "#fff",
                textTransform: "none",
                fontFamily: "'Figtree', sans-serif",
                fontWeight: 600,
                fontSize: 20,
                borderRadius: 2,
                px: 2,
                py: 2,
                mt: 1, mb: 1
              }}
            >
              Apply for Fellowship
            </Button>
          </Box>

          {/* Mobile Menu Icon */}
          <IconButton
            color="inherit"
            edge="end"
            onClick={toggleDrawer}
            sx={{ display: { xs: "flex", md: "none" } }}
          >
            {drawerOpen ? <CloseIcon sx={{ color: "#000" }} /> : <MenuIcon sx={{ color: "#000" }} />}
            <MenuIcon />
          </IconButton>
        </Toolbar>
      </AppBar>

      {/* Mobile Drawer */}
      <Drawer
        anchor="right"
        open={drawerOpen}
        onClose={toggleDrawer}
        PaperProps={{
          sx: {
            width: "100%",
            height: "100%",
            backgroundColor: "#fff",
            display: "flex",
            flexDirection: "column",
          },
        }}
      >
        {/* Drawer Header: Logo + Close Icon */}
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            px: 4,
            pt: 3,
            pb: 2,
            borderBottom: "1px solid #ddd",
          }}
        >
          <Typography
            variant="h6"
            component={Link}
            to="/"
            sx={{
              textDecoration: "none",
              color: "#000",
              fontFamily: "'Figtree', sans-serif",
              fontWeight: 600,
            }}
            onClick={toggleDrawer} // navigate and close
          >
            MyLogo
          </Typography>

          {/* Close Icon */}
          <IconButton onClick={toggleDrawer}>
            <CloseIcon sx={{  color: "#000" }} />
          </IconButton>
        </Box>

        {/* Nav Items */}
        <Box sx={{ flexGrow: 1, px: 0, mt: 4 }}>
          <List>
            {navLinks.map((link) => (
              <ListItem
                key={link.name}
                component={Link}
                to={link.path}
                onClick={toggleDrawer}
                sx={{ mb: 3 }}
              >
                <ListItemText
                  primary={
                    <Typography
                      sx={{
                        fontFamily: "'Figtree', sans-serif",
                        fontWeight: 600,
                        fontSize: 20,
                        color: "#000",
                        textAlign: 'left'
                      }}
                    >
                      {link.name}
                    </Typography>
                  }
                />
              </ListItem>
            ))}
          </List>
        </Box>

        {/* Bottom Apply Button */}
        <Box sx={{ px: 4, pb: 4 }}>
          <Button
            variant="contained"
            fullWidth
            component={Link}
            to="/apply"
            sx={{
              backgroundColor: btnColor,
              color: "#fff",
              fontFamily: "'Figtree', sans-serif",
              fontWeight: 600,
              fontSize: 18,
              py: 2,
            }}
            onClick={toggleDrawer}
          >
            Apply for Fellowship
          </Button>
        </Box>
      </Drawer>
    </>
  );
};

export default Header;