import React, { useState, useEffect, useRef } from "react";
import {
  Container,
  Box,
  Typography,
  TextField,
  Button,
  Alert,
  CircularProgress
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../contexts/AuthContext";

export default function OTPVerification() {
  const navigate = useNavigate();
  const [otp, setOtp] = useState(["", "", "", "", "", ""]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [resendDisabled, setResendDisabled] = useState(true);
  const [timer, setTimer] = useState(30);
  const inputRefs = useRef([]);
  const { setOtpVerified, mobileNumber } = useAuth();

  useEffect(() => {
    if (!mobileNumber) navigate("/login"); // Guard
  }, [mobileNumber, navigate]);


  // Timer logic
  useEffect(() => {
    let interval;
    if (resendDisabled && timer > 0) {
      interval = setInterval(() => {
        setTimer((prev) => prev - 1);
      }, 1000);
    } else if (timer === 0) {
      setResendDisabled(false);
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [resendDisabled, timer]);

  // Handle OTP input change
  const handleChange = (index, value) => {
    if (value.length <= 1 && /^\d*$/.test(value)) {
      const newOtp = [...otp];
      newOtp[index] = value;
      setOtp(newOtp);
      setError("");

      // Auto-focus next input
      if (value && index < 5) {
        inputRefs.current[index + 1].focus();
      }
    }
  };

  // Handle key press (backspace)
  const handleKeyDown = (index, e) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      inputRefs.current[index - 1].focus();
    }
  };

  // Handle paste event
  const handlePaste = (e) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData("text").slice(0, 6);
    if (/^\d+$/.test(pastedData)) {
      const otpArray = pastedData.split("");
      const newOtp = [...otp];
      for (let i = 0; i < Math.min(otpArray.length, 6); i++) {
        newOtp[i] = otpArray[i];
      }
      setOtp(newOtp);
      
      // Focus last filled input
      const lastFilledIndex = Math.min(otpArray.length, 5);
      if (lastFilledIndex < 6) {
        inputRefs.current[lastFilledIndex].focus();
      }
    }
  };

  // Handle OTP verification
  const handleVerify = async () => {
    const otpValue = otp.join("");
    
    if (otpValue.length !== 6) {
      setError("Please enter complete 6-digit OTP");
      return;
    }

    setLoading(true);
    
    // Simulate API call
    setTimeout(() => {
      if (otpValue === "123456") {
        setOtpVerified(true);
        // Success - navigate to success page
        navigate("/success");
      } else {
        setError("Invalid OTP. Please try again.");
        setOtp(["", "", "", "", "", ""]);
        inputRefs.current[0].focus();
      }
      setLoading(false);
    }, 1500);
  };

  // Handle resend OTP
  const handleResend = () => {
    setResendDisabled(true);
    setTimer(30);
    setError("");
    setOtp(["", "", "", "", "", ""]);
    inputRefs.current[0].focus();
    
    // Simulate API call to resend OTP
    console.log("Resending OTP...");
  };

  return (
    <Container
      maxWidth="xl"
      sx={{
        height: "100vh",
        position: "relative",
        display: "flex",
        alignItems: "center",
        justifyContent: "center"
      }}
    >
      {/* TOP LEFT LOGO */}
      <Box
        sx={{
          position: "absolute",
          top: "25px",
          left: "25px"
        }}
      >
        <img
          src="/venum-logo.png"
          alt="Venum"
          style={{ width: "120px" }}
        />
      </Box>

      {/* CENTER CONTENT */}
      <Box
        sx={{
          width: "100%",
          maxWidth: "450px",
          textAlign: "center",
          margin: "0 auto"
        }}
      >
        <Typography
          variant="h4"
          fontWeight="bold"
          mb={1}
        >
          Verify OTP
        </Typography>

        <Typography
          color="text.secondary"
          mb={4}
        >
          We've sent a 6-digit verification code to your mobile number
        </Typography>

        {/* OTP INPUT FIELDS */}
        <Box
          sx={{
            display: "flex",
            gap: 1.5,
            justifyContent: "center",
            mb: 3,
            flexWrap: "wrap"
          }}
        >
          {otp.map((digit, index) => (
            <TextField
              key={index}
              inputRef={(el) => (inputRefs.current[index] = el)}
              value={digit}
              onChange={(e) => handleChange(index, e.target.value)}
              onKeyDown={(e) => handleKeyDown(index, e)}
              onPaste={index === 0 ? handlePaste : undefined}
              inputProps={{
                maxLength: 1,
                style: {
                  textAlign: "center",
                  fontSize: "24px",
                  fontWeight: "bold",
                  padding: "12px 0"
                }
              }}
              sx={{
                width: "55px",
                "& .MuiOutlinedInput-root": {
                  borderRadius: "12px",
                  backgroundColor: "#f5f5f5",
                  "&:hover fieldset": {
                    borderColor: "#000"
                  },
                  "&.Mui-focused fieldset": {
                    borderColor: "#000",
                    borderWidth: "2px"
                  }
                }
              }}
            />
          ))}
        </Box>

        {/* ERROR MESSAGE */}
        {error && (
          <Alert severity="error" sx={{ mb: 2, borderRadius: "8px" }}>
            {error}
          </Alert>
        )}

        {/* VERIFY BUTTON */}
        <Button
          fullWidth
          variant="contained"
          onClick={handleVerify}
          disabled={loading}
          sx={{
            backgroundColor: "black",
            color: "white",
            height: "50px",
            fontSize: "16px",
            borderRadius: "8px",
            mb: 3,
            "&:hover": {
              backgroundColor: "#222"
            },
            "&.Mui-disabled": {
              backgroundColor: "#ccc"
            }
          }}
        >
          {loading ? <CircularProgress size={24} color="inherit" /> : "Verify OTP"}
        </Button>

        {/* RESEND OTP WITH TIMER */}
        <Box sx={{ textAlign: "center" }}>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            Didn't receive the code?
          </Typography>
          
          {resendDisabled ? (
            <Typography variant="body2" sx={{ fontWeight: "medium", color: "#666" }}>
              Resend code in {timer} seconds
            </Typography>
          ) : (
            <Button
              onClick={handleResend}
              sx={{
                color: "black",
                fontWeight: "bold",
                textTransform: "none",
                fontSize: "14px",
                "&:hover": {
                  backgroundColor: "transparent",
                  textDecoration: "underline"
                }
              }}
            >
              Resend OTP
            </Button>
          )}
        </Box>

        {/* BACK TO LOGIN LINK */}
        <Button
          onClick={() => navigate("/login")}
          sx={{
            mt: 3,
            color: "#666",
            textTransform: "none",
            "&:hover": {
              backgroundColor: "transparent",
              color: "black"
            }
          }}
        >
          ← Back to Login
        </Button>
      </Box>
    </Container>
  );
}