import React, { useState } from "react";
import {
  Container,
  Box,
  Typography,
  TextField,
  Button,
  Paper,
  Alert
} from "@mui/material";
import { useNavigate } from "react-router-dom";

export default function UserDetails() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    fullName: "",
    email: ""
  });
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
    // Clear error for this field when user starts typing
    if (errors[name]) {
      setErrors({
        ...errors,
        [name]: ""
      });
    }
  };

  // Validate form
  const validateForm = () => {
    const newErrors = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = "Full name is required";
    } else if (formData.fullName.trim().length < 3) {
      newErrors.fullName = "Name must be at least 3 characters";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Please enter a valid email address";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Handle submit
  const handleSubmit = () => {
    if (validateForm()) {
      setSubmitted(true);
      setSaveSuccess(true);
      // Simulate API call
      setTimeout(() => {
        setSubmitted(false);
        navigate("/");
        // Navigate to dashboard or next page after successful submission
        // navigate("/dashboard");
      }, 1500);
    }
  };

  // Handle Enter key press
  const handleKeyPress = (e) => {
    if (e.key === "Enter") {
      handleSubmit();
    }
  };

  return (
    <Container
      maxWidth={false}
      sx={{
        height: "100vh",
        position: "relative",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        backgroundColor: "#FFF"
      }}
    >
      {/* TOP LEFT LOGO */}
      <Box
        sx={{
          position: "absolute",
          top: "25px",
          left: "25px"
        }}
      >
        <img
          src="/venum-logo.png"
          alt="Venum"
          style={{ width: "120px" }}
        />
      </Box>

      {/* CENTER CONTENT - 50% WIDTH */}
      <Box
        sx={{
          width: "50%",
          maxWidth: "600px",
          minWidth: "300px",
          margin: "0 auto"
        }}
      >
        <Paper
          elevation={3}
          sx={{
            p: 5,
            // borderRadius: "20px",
            backgroundColor: "#fff",
            boxShadow: "none"
          }}
        >
          {/* Title */}
          <Typography
            variant="h4"
            fontWeight="bold"
            sx={{
              mb: 1,
              textAlign: "center",
              color: "#000",
              fontSize: { xs: "1.8rem", sm: "2rem", md: "2.2rem" }
            }}
          >
            User Details
          </Typography>

          {/* Description */}
          <Typography
            color="text.secondary"
            sx={{
              mb: 4,
              textAlign: "center",
              fontSize: "1rem"
            }}
          >
            Please provide your information to complete your profile
          </Typography>

          {/* Success Message */}
          {saveSuccess && (
            <Alert
              severity="success"
              sx={{
                mb: 3,
                borderRadius: "8px",
                animation: "fadeIn 0.5s ease-out"
              }}
              onClose={() => setSaveSuccess(false)}
            >
              Details saved successfully!
            </Alert>
          )}

          {/* Submitting Message */}
          {submitted && !saveSuccess && (
            <Alert
              severity="info"
              sx={{
                mb: 3,
                borderRadius: "8px"
              }}
            >
              Saving your details...
            </Alert>
          )}

          {/* Full Name Field */}
          <Typography
            sx={{
              mb: 1,
              fontWeight: "medium",
              color: "#333",
              textAlign: 'left'
            }}
          >
            Full Name
          </Typography>
          <TextField
            name="fullName"
            placeholder="Enter your full name"
            value={formData.fullName}
            onChange={handleChange}
            onKeyPress={handleKeyPress}
            fullWidth
            error={!!errors.fullName}
            helperText={errors.fullName}
            sx={{
              mb: 3,
              "& .MuiOutlinedInput-root": {
                borderRadius: "12px",
                backgroundColor: "#fafafa",
                "&:hover fieldset": {
                  borderColor: "#000"
                },
                "&.Mui-focused fieldset": {
                  borderColor: "#000",
                  borderWidth: "2px"
                }
              },
              "& .MuiInputLabel-root.Mui-focused": {
                color: "#000"
              }
            }}
          />

          {/* Email Field */}
          <Typography
            sx={{
              mb: 1,
              fontWeight: "medium",
              color: "#333",
              textAlign: 'left'
            }}
          >
            Email Address
          </Typography>
          <TextField
            name="email"
            type="email"
            placeholder="Enter your email address"
            value={formData.email}
            onChange={handleChange}
            onKeyPress={handleKeyPress}
            fullWidth
            error={!!errors.email}
            helperText={errors.email}
            sx={{
              mb: 4,
              "& .MuiOutlinedInput-root": {
                borderRadius: "12px",
                backgroundColor: "#fafafa",
                "&:hover fieldset": {
                  borderColor: "#000"
                },
                "&.Mui-focused fieldset": {
                  borderColor: "#000",
                  borderWidth: "2px"
                }
              },
              "& .MuiInputLabel-root.Mui-focused": {
                color: "#000"
              }
            }}
          />

          {/* Save & Update Button */}
          <Button
            variant="contained"
            fullWidth
            size="large"
            onClick={handleSubmit}
            disabled={submitted}
            sx={{
              backgroundColor: "black",
              color: "white",
              height: "52px",
              fontSize: "16px",
              fontWeight: "bold",
              borderRadius: "12px",
              textTransform: "none",
              mb: 2,
              "&:hover": {
                backgroundColor: "#222",
                transform: "translateY(-2px)",
                boxShadow: "0 5px 15px rgba(0,0,0,0.2)"
              },
              "&.Mui-disabled": {
                backgroundColor: "#ccc",
                color: "#666"
              },
              transition: "all 0.3s ease"
            }}
          >
            {submitted ? "Saving..." : "Save & Update"}
          </Button>

          {/* Back Link */}
          <Button
            onClick={() => navigate(-1)}
            sx={{
              color: "#666",
              textTransform: "none",
              fontSize: "14px",
              fontWeight: "medium",
              "&:hover": {
                backgroundColor: "transparent",
                color: "black",
                textDecoration: "underline"
              }
            }}
            fullWidth
          >
            ← Go Back
          </Button>
        </Paper>
      </Box>

      {/* Animation Keyframes */}
      <style>
        {`
          @keyframes fadeIn {
            from {
              opacity: 0;
              transform: translateY(-10px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
        `}
      </style>
    </Container>
  );
}